package dev.presidencia;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.network.RegistryByteBuf;
public class V032Tests implements FabricGameTest {
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=20) public void voiceRangeKeepsNearbySpeechAudible(TestContext c){c.assertEquals(ModAudio.attenuation(0,10),1d,"No fade at companion distance");c.assertEquals(ModAudio.attenuation(0,24),1d,"Full volume through 24 blocks");c.assertEquals(ModAudio.attenuation(0,44),.5d,"Smooth midrange");c.assertEquals(ModAudio.attenuation(0,64),0d,"Ends at 64 blocks");c.assertEquals(ModAudio.attenuation(1,40),0d,"Other effects end at 40");c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=20) public void audioPacketPreservesPlaybackParameters(TestContext c){var buffer=new RegistryByteBuf(io.netty.buffer.Unpooled.buffer(),c.getWorld().getRegistryManager());try{var original=new ModSoundPacket(Terror.id("lula_beer"),0,1.25,2.5,3.75,.8f,1.1f,true);ModSoundPacket.CODEC.encode(buffer,original);c.assertEquals(ModSoundPacket.CODEC.decode(buffer),original,"Packet roundtrip");}finally{buffer.release();}c.complete();}
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=20) public void memeEventsHaveEmbeddedAudio(TestContext c){try(var stream=V032Tests.class.getResourceAsStream("/assets/presidencia_terror/sounds.json")){var sounds=com.google.gson.JsonParser.parseReader(new java.io.InputStreamReader(stream)).getAsJsonObject();int count=0;for(var event:sounds.entrySet()){if(!event.getKey().startsWith("lula_")&&!event.getKey().startsWith("bolsonaro_"))continue;var files=event.getValue().getAsJsonObject().getAsJsonArray("sounds");c.assertTrue(!files.isEmpty(),"Voice event populated");for(var file:files){String name=file.getAsJsonObject().get("name").getAsString().split(":")[1];try(var audio=V032Tests.class.getResourceAsStream("/assets/presidencia_terror/sounds/"+name+".ogg")){c.assertTrue(audio!=null,"Embedded voice exists");count++;}}}c.assertTrue(count>=13,"All voice mappings integrated");}catch(java.io.IOException e){throw new RuntimeException(e);}c.complete();}
}
